export function getSignalPressCopy(locale: Locale): SignalPressCopy {
  if (locale === "tr" || locale === "en") return { ...(locale === "tr" ? tr : en), headline: signalHeadlines[locale][0], headlineAccent: signalHeadlines[locale][1], ...costCopy[locale], ...proofStates[locale], ...editorLabels[locale], ...antiViralityCopy[locale], ...translatedInteractionLabels[locale], ...revisionLabels[locale], contributing: contributionLabels[locale], contentLocale: locale };
  const { landing } = getDictionary(locale);
  const marketing = landingMarketing[locale];
  return {
    ...en,
    ...costCopy[locale],
    ...proofStates[locale],
    ...editorLabels[locale],
    ...antiViralityCopy[locale],
    contentLocale: locale,
    languageNotice: "",
    menu: landing.menuLabel,
    heroKicker: landing.footer,
    headline: signalHeadlines[locale][0],
    headlineAccent: signalHeadlines[locale][1],
    intro: landing.intro,
    explore: landing.opportunity,
    code: landing.sourceCode,
    issue: landing.opportunity,
    source: landing.sourcePost,
    inspect: landing.draft,
    selected: landing.sourcePost,
    fit: landing.opportunity,
    reason: landing.opportunityDetail,
    writingKicker: landing.draft,
    writingIntro: marketing.voiceDetail,
    diffAdded: landing.draftDetail,
    approval: landing.outcomeDetail,
    proofKicker: landing.outcome,
    proof: landing.outcome,
    manifestoKicker: landing.sourceCode,
    manifestoTitle: landing.localTitle,
    manifestoBody: landing.intro,
    install: landing.sourceCode,
    repo: landing.sourceCode,
    limitations: marketing.controlDetail,
    transparency: landing.trustLabel,
    research: landing.flowTitle,
    footerLabel: landing.trustLabel,
    archive: `${landing.headlineFirst} ${landing.headlineSecond}`,
    archiveBody: `${landing.flowTitle} · ${marketing.afterDetail}`,
    archiveToggle: landing.sourceCode,
    signature: "ISPATLA",
    examples: ["@productnotes", "@dailyhacks", "@openrecords"].map((source, index) => ({
      id: `localized-${index}`,
      source,
      post: localizedSamples[locale].posts[index],
      verdict: index === 1 ? "reject" as const : "keep" as const,
      score: [72, 18, 64][index],
      reason: localizedExampleCopy[locale].reasons[index],
      draft: localizedExampleCopy[locale].drafts[index],
      revised: localizedExampleCopy[locale].revisions[index],
    })),
    ...translatedInteractionLabels[locale],
    ...revisionLabels[locale],
    contributing: contributionLabels[locale],
  };
}
